"""Seating charts: students in rows by last name."""

from typing import List, Tuple

from rosterkit.models import Student

def seat_key(student: Student) -> Tuple[str, str]:
    """Last name first, then first name, ignoring case."""
    last = student.last_name.casefold()
    first = student.first_name.casefold()
    return (last, first)

def check_arguments(
    students: List[Student], seats_per_row: int
) -> None:
    """Refuse input that cannot make a seating chart."""
    if seats_per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def split_rows(
    ordered: List[Student], seats_per_row: int
) -> List[List[Student]]:
    """Cut a sorted list into runs of seats_per_row."""
    rows = []
    for start in range(0, len(ordered), seats_per_row):
        rows.append(ordered[start:start + seats_per_row])
    return rows

def format_row(number: int, members: List[Student]) -> str:
    """Text for one row, seats in the order given."""
    names = [member.display_name for member in members]
    return f"Row {number}: " + " | ".join(names)

def format_rows(rows: List[List[Student]]) -> List[str]:
    """Number the rows from one and render each as text."""
    lines = []
    for number, members in enumerate(rows, 1):
        lines.append(format_row(number, members))
    return lines

def seating_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One line of text per row, sorted by last name."""
    check_arguments(students, seats_per_row)
    ordered = sorted(students, key=seat_key)
    return format_rows(split_rows(ordered, seats_per_row))

