import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

ROSTER = [
    ("Quillon", "Sefa"), ("Halloway", "Juno"),
    ("Dunmere", "Piet"), ("Halloway", "Abel")
]

def rows_for(pairs, seats):
    """Seating rows for (last, first) pairs."""
    students = [
        Student(str(number), last, first, "A")
        for number, (last, first) in enumerate(pairs, 1)
    ]
    return seating_rows(students, seats)

class SeatingRowsTests(unittest.TestCase):
    def test_sorted_by_last_then_first_name(self):
        rows = rows_for(ROSTER, 2)
        expected = [
            "Row 1: Dunmere, Piet | Halloway, Abel",
            "Row 2: Halloway, Juno | Quillon, Sefa"
        ]
        self.assertEqual(rows, expected)

    def test_last_row_can_be_short(self):
        rows = rows_for(ROSTER, 3)
        self.assertEqual(len(rows), 2)
        self.assertEqual(rows[1], "Row 2: Quillon, Sefa")

    def test_sorting_ignores_case(self):
        pairs = [("Brook", "Ann"), ("adams", "Bo")]
        rows = rows_for(pairs, 2)
        expected = ["Row 1: adams, Bo | Brook, Ann"]
        self.assertEqual(rows, expected)

    def test_zero_seats_rejected(self):
        with self.assertRaises(ValueError):
            rows_for(ROSTER, 0)

    def test_negative_seats_rejected(self):
        with self.assertRaises(ValueError):
            rows_for(ROSTER, -3)

    def test_no_students_rejected(self):
        with self.assertRaises(ValueError):
            rows_for([], 2)
